using Domain.Entities;
using Domain.Helpers;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;

namespace Infrastructure.Persistence;

public static class BlogPostSeedData
{
    public static List<BlogPost> GetPosts()
    {
        var markdown = Encoding.UTF8.GetString(Convert.FromBase64String(RawMarkdownBase64));
        var lines = markdown.Split(new[] { "\r\n", "\n" }, StringSplitOptions.None);
        var posts = new List<BlogPost>();
        var usedSlugs = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var currentSection = "Blog";
        var coverPool = new[]
        {
            "/images/hero-illustration-business.png",
            "/images/hero-illustration-customer.png",
            "/images/hero-illustration.png"
        };

        int? order = null;
        string? title = null;
        var contentLines = new List<string>();

        void FlushCurrent()
        {
            if (string.IsNullOrWhiteSpace(title)) return;

            var baseSlug = SlugHelper.Slugify(title);
            var slug = EnsureUniqueSlug(baseSlug, usedSlugs);
            usedSlugs.Add(slug);

            var summary = BuildSummary(contentLines);
            var content = ConvertMarkdownToHtml(contentLines);
            var index = posts.Count;
            var tags = BuildTags(currentSection, title);

            posts.Add(new BlogPost
            {
                Id = CreateDeterministicGuid($"seed-md:{slug}"),
                Title = title,
                Slug = slug,
                Summary = summary,
                Content = content,
                CoverImageUrl = coverPool[index % coverPool.Length],
                IsPublished = true,
                PublishedAt = new DateTime(2026, 3, 1).AddDays((order ?? index + 1) - 1),
                Tags = tags
            });

            order = null;
            title = null;
            contentLines.Clear();
        }

        foreach (var rawLine in lines)
        {
            var line = rawLine.Trim();

            if (line.StartsWith("## ", StringComparison.Ordinal))
            {
                FlushCurrent();
                currentSection = line[3..].Trim();
                continue;
            }

            if (line.StartsWith("### ", StringComparison.Ordinal))
            {
                FlushCurrent();
                var header = line[4..].Trim();
                var match = Regex.Match(header, @"^(?<n>\d+)\.\s*(?<t>.+)$");
                if (match.Success)
                {
                    order = int.Parse(match.Groups["n"].Value);
                    title = match.Groups["t"].Value.Trim();
                }
                else
                {
                    title = header;
                }
                continue;
            }

            if (!string.IsNullOrWhiteSpace(title))
            {
                contentLines.Add(rawLine);
            }
        }

        FlushCurrent();
        return posts;
    }

    private static string ConvertMarkdownToHtml(List<string> lines)
    {
        var sb = new StringBuilder();
        var paragraph = new StringBuilder();
        var inList = false;

        void FlushParagraph()
        {
            if (paragraph.Length == 0) return;
            sb.Append("<p>");
            sb.Append(WebUtility.HtmlEncode(paragraph.ToString().Trim()));
            sb.AppendLine("</p>");
            paragraph.Clear();
        }

        void CloseList()
        {
            if (!inList) return;
            sb.AppendLine("</ul>");
            inList = false;
        }

        foreach (var rawLine in lines)
        {
            var line = rawLine.Trim();

            if (string.IsNullOrWhiteSpace(line))
            {
                FlushParagraph();
                CloseList();
                continue;
            }

            if (line.StartsWith("**", StringComparison.Ordinal) && line.EndsWith("**", StringComparison.Ordinal) && line.Length > 4)
            {
                FlushParagraph();
                CloseList();
                sb.Append("<h2>");
                sb.Append(WebUtility.HtmlEncode(line[2..^2].Trim()));
                sb.AppendLine("</h2>");
                continue;
            }

            if (line.StartsWith("- ", StringComparison.Ordinal))
            {
                FlushParagraph();
                if (!inList)
                {
                    sb.AppendLine("<ul>");
                    inList = true;
                }
                sb.Append("<li>");
                sb.Append(WebUtility.HtmlEncode(line[2..].Trim()));
                sb.AppendLine("</li>");
                continue;
            }

            CloseList();
            if (paragraph.Length > 0) paragraph.Append(' ');
            paragraph.Append(line);
        }

        FlushParagraph();
        CloseList();
        return sb.ToString();
    }

    private static string BuildSummary(List<string> lines)
    {
        var firstText = lines
            .Select(x => x.Trim())
            .FirstOrDefault(x =>
                !string.IsNullOrWhiteSpace(x) &&
                !x.StartsWith("**", StringComparison.Ordinal) &&
                !x.StartsWith("- ", StringComparison.Ordinal));

        if (string.IsNullOrWhiteSpace(firstText))
        {
            return "Restoran işletmeciliği ve dijital menü üzerine rehber içerik.";
        }

        return firstText.Length > 250 ? $"{firstText[..247]}..." : firstText;
    }

    private static string BuildTags(string section, string title)
    {
        var tags = new List<string>();

        if (section.Contains("QR Menü", StringComparison.OrdinalIgnoreCase))
        {
            tags.AddRange(new[] { "qr-menu", "dijital-menu", "restoran" });
        }
        else if (section.Contains("İşletmeciliği", StringComparison.OrdinalIgnoreCase))
        {
            tags.AddRange(new[] { "restoran", "isletmecilik", "yonetim" });
        }
        else if (section.Contains("Yemek", StringComparison.OrdinalIgnoreCase) || section.Contains("Mutfak", StringComparison.OrdinalIgnoreCase))
        {
            tags.AddRange(new[] { "yemek", "mutfak", "menu" });
        }
        else
        {
            tags.Add("blog");
        }

        var normalizedTitleTag = SlugHelper.Slugify(title);
        if (!string.IsNullOrWhiteSpace(normalizedTitleTag))
        {
            tags.Add(normalizedTitleTag);
        }

        return string.Join(",", tags.Distinct(StringComparer.OrdinalIgnoreCase).Take(4));
    }

    private static string EnsureUniqueSlug(string slug, HashSet<string> usedSlugs)
    {
        if (string.IsNullOrWhiteSpace(slug)) slug = "blog-yazisi";
        if (!usedSlugs.Contains(slug)) return slug;

        var i = 2;
        while (true)
        {
            var suffix = $"-{i}";
            var maxBaseLen = Math.Max(1, 30 - suffix.Length);
            var trimmedBase = slug[..Math.Min(slug.Length, maxBaseLen)].TrimEnd('-');
            var candidate = $"{trimmedBase}{suffix}";
            if (!usedSlugs.Contains(candidate)) return candidate;
            i++;
        }
    }

    private static Guid CreateDeterministicGuid(string input)
    {
        var bytes = MD5.HashData(Encoding.UTF8.GetBytes(input));
        return new Guid(bytes);
    }

    private const string RawMarkdownBase64 = "";
}
